package leetcode.medium;

import org.junit.Test;
import static org.junit.Assert.*;

public class OnlineStockSpanTest {

    @Test
    public void nextTest() {
        OnlineStockSpan span = new OnlineStockSpan();
        assertEquals(1, span.next(5));
        assertEquals(1, span.next(3));
        assertEquals(2, span.next(5));
        assertEquals(1, span.next(1));
        assertEquals(5, span.next(5));
    }

    @Test
    public void nextWithDecreasingPricesTest() {
        OnlineStockSpan span = new OnlineStockSpan();
        assertEquals(1, span.next(300));
        assertEquals(1, span.next(200));
        assertEquals(1, span.next(100));
        assertEquals(1, span.next(50));
    }

    @Test
    public void nextWithIncreasingPricesTest() {
        OnlineStockSpan span = new OnlineStockSpan();
        assertEquals(1, span.next(50));
        assertEquals(2, span.next(100));
        assertEquals(3, span.next(200));
        assertEquals(4, span.next(300));
    }

    @Test
    public void calculateSpansTest(){
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int [] prices = {10, 4, 5, 90, 120, 80};
        int [] expected = {1, 1, 2, 4, 5, 1};
        assertArrayEquals(expected, onlineStockSpan.calculateSpans(prices));
    }

    @Test
    public void calculateSpansWithSamePricesTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {100, 100, 100, 100, 100};
        int[] expected = {1, 2, 3, 4, 5};
        assertArrayEquals(expected, onlineStockSpan.calculateSpans(prices));
    }

    @Test
    public void calculateSpansWithDecreasingPricesTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {300, 200, 100, 50, 10};
        int[] expected = {1, 1, 1, 1, 1};
        assertArrayEquals(expected, onlineStockSpan.calculateSpans(prices));
    }

    @Test
    public void calculateSpansWithIncreasingPricesTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {50, 100, 150, 200, 250, 300};
        int[] expected = {1, 2, 3, 4, 5, 6};
        assertArrayEquals(expected, onlineStockSpan.calculateSpans(prices));
    }
}
